; -----------------------------------------------------------------------------
; SpritePatterns
; -----------------------------------------------------------------------------
; Two 8x8 sprites. Sprite pattern 0 is used by the player.
; -----------------------------------------------------------------------------
SpritePatterns:
        ; Pattern 0: player/ship.
        DB      $18,$3C,$7E,$DB,$FF,$24,$66,$C3

        ; Pattern 1: reserve/enemy marker.
        DB      $18,$3C,$7E,$FF,$DB,$24,$42,$81
SpritePatterns_End:
